const milestones = $input.all().map(i => i.json);

if (milestones.length === 0) {
  return [{ json: { text: '📅 *No upcoming milestones this week.* All quiet.' } }];
}

let msg = '📅 *Upcoming Milestones (next 7 days):*\n\n';
milestones.forEach(m => {
  const client = m.client;
  const name = `${client.first_name} ${client.last_name}`;
  msg += `• *${m.milestone_date}* — ${m.title} (${m.milestone_type}) — ${name}\n`;
});

msg += '\n_Send a personal note? Reply here and J9 will draft it in Janine\'s voice._';

return [{ json: { text: msg } }];
